pub fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    let n = vals_1.len();
    assert_eq!(vals_2.len(), n);
    assert_eq!(conds_1.len(), n);
    assert_eq!(conds_2.len(), n);

    // Overwrite any previous contents and ensure exact length n.
    avgs.clear();
    avgs.reserve(n);

    for i in 0..n {
        let c1 = conds_1[i];
        let c2 = conds_2[i];
        assert!(c1 || c2, "At least one condition must be true at each index");

        let a = vals_1[i];
        let b = vals_2[i];
        assert!(a < 1000 && b < 1000, "All input integers must be < 1000");

        let out = match (c1, c2) {
            (true, true) => (a + b) / 2,
            (true, false) => a,
            (false, true) => b,
            (false, false) => unreachable!(),
        };

        avgs.push(out);
    }

    debug_assert_eq!(avgs.len(), n);
}